document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("stats-grid");n&&(n.innerHTML=TANTIA_INFO.quickStats.map(n=>`\n                <div class="stat-pill">\n                    <span class="stat-icon">${n.icon}</span>\n                    <span class="stat-value">${n.value}</span>\n                    <span class="stat-label">${n.label}</span>\n                </div>\n            `).join(""));const t=document.getElementById("history-content");t&&(t.innerHTML=`\n            <h3>${HISTORY_TEXT.title}</h3>\n            ${HISTORY_TEXT.paragraphs.map(n=>`<p>${n}</p>`).join("")}\n        `);const e=document.getElementById("tb-timeline");e&&(e.innerHTML=TIMELINE_EVENTS.map((n,t)=>`\n                <button type="button" class="tb-timeline-item" data-index="${t}" aria-expanded="false">\n                    <div class="tb-timeline-dot"></div>\n                    <div class="tb-timeline-content">\n                        <span class="tb-timeline-era">${n.era}</span>\n                        <h4>${n.title}</h4>\n                        <p class="tb-timeline-desc">${n.description}</p>\n                    </div>\n                    <span class="tb-timeline-caret">▾</span>\n                </button>\n            `).join(""),e.querySelectorAll(".tb-timeline-item").forEach(n=>{n.addEventListener("click",()=>{const t=n.classList.toggle("tb-timeline-open");n.setAttribute("aria-expanded",String(t))})}));const a=document.getElementById("resistance-grid");a&&(a.innerHTML=RESISTANCE_POINTS.map(n=>`\n                <div class="tb-card">\n                    <h4>${n.title}</h4>\n                    <p>${n.description}</p>\n                </div>\n            `).join(""));const i=document.getElementById("legacy-content");i&&(i.innerHTML=LEGACY_TEXT.paragraphs.map(n=>`<p>${n}</p>`).join(""));const s=document.getElementById("tb-gallery");s&&(s.innerHTML=GALLERY_QUERIES.map(n=>`<div class="tb-gallery-tile"><span>${n}</span></div>`).join(""));const l=document.getElementById("references-list");l&&(l.innerHTML=REFERENCES.map(n=>`<li><a href="${n.link}" target="_blank" rel="noopener">${n.text}</a></li>`).join(""))});